WITH with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_session FROM transactions), sessions_transactions AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT s.id, s.account_id, s.txn_type, s.amount, s.merchant, s.is_flagged, CASE WHEN merchant RLIKE '^(Starbucks|Grab)$' THEN 'EXTENDED' ELSE 'OTHER_ZONE' END AS merchant_zone, (SELECT AVG(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS avg_transaction_amount FROM sessions_transactions s ORDER BY merchant DESC NULLS LAST, id
